const inboxStatusNames={new:'جديد',extracting:'جارٍ استخراج المرفقات',ready:'جاهز للفرز',needs_review:'يحتاج مراجعة',imported:'تم استيراده',failed:'فشل الاستيراد',duplicate:'بريد مكرر'} as const
